# qstr constants, dynamically constructed strings and bytes, UTF-8/NUL.
for value in ("", "abc", "a\x00b", "é😀", b"", b"abc", b"a\x00b", b"\xff\x00\x80", b"\x10\xc8="):
    data = value.encode() if isinstance(value, str) else value
    h = 5381
    for b in data:
        h = ((h * 33) ^ b) & 65535
    check(value, h or 1)
    dynamic = value[:1] + value[1:]
    check(dynamic, h or 1)
# Pointer seeds differ between the VM and oracle; compare element deltas.
assert hash((1, -2, 3.5)) - hash(()) == 2
assert hash(frozenset((1, -2, 3.5))) - hash(frozenset()) == 2
class Key:
    def __hash__(self):
        return -37
check(Key(), -37)
for value in ([], {}, set(), bytearray(b"a")):
    try:
        hash(value)
        raise ValueError("unhashable accepted")
    except TypeError:
        pass
print("hash equivalence ok")
